class Solution {
    private int[] arr;
    public int reversePairs(int[] nums) {
        arr = nums;
        return sort(0, nums.length);
    }
    private int sort(int lo, int hi) {
        if (hi - lo <= 1) return 0;
        int mid = (lo + hi) >>> 1;
        int cnt = sort(lo, mid) + sort(mid, hi);
        int j = mid;
        for (int i = lo; i < mid; i++) {
            while (j < hi && (long) arr[i] > 2L * arr[j]) j++;
            cnt += j - mid;
        }
        int[] merged = new int[hi - lo];
        int p = lo, q = mid, k = 0;
        while (p < mid && q < hi) merged[k++] = arr[p] <= arr[q] ? arr[p++] : arr[q++];
        while (p < mid) merged[k++] = arr[p++];
        while (q < hi) merged[k++] = arr[q++];
        System.arraycopy(merged, 0, arr, lo, merged.length);
        return cnt;
    }
}

