import bisect
class Solution:
    def reversePairs(self, nums: List[int]) -> int:
        vals = sorted(set(nums))
        rank = {v: i + 1 for i, v in enumerate(vals)}
        n = len(vals)
        tree = [0] * (n + 1)
        def update(i):
            while i <= n:
                tree[i] += 1
                i += i & (-i)
        def query(i):
            s = 0
            while i > 0:
                s += tree[i]
                i -= i & (-i)
            return s
        ans = 0
        for x in reversed(nums):
            # count inserted v with 2*v < x  <=>  v < x/2
            idx = bisect.bisect_left(vals, (x + 1) // 2) if x > 0 else bisect.bisect_left(vals, -(-x // 2))
            # safer: find largest v with 2*v < x
            lo, hi = 0, len(vals)
            while lo < hi:
                m = (lo + hi) // 2
                if 2 * vals[m] < x: lo = m + 1
                else: hi = m
            ans += query(lo)
            update(rank[x])
        return ans

