class Solution {
    vector<int> tree;
    void update(int i, int n) { for (; i <= n; i += i & (-i)) tree[i]++; }
    int query(int i) { int s = 0; for (; i > 0; i -= i & (-i)) s += tree[i]; return s; }
public:
    int reversePairs(vector<int>& nums) {
        vector<long long> vals(nums.begin(), nums.end());
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        int n = vals.size();
        tree.assign(n + 1, 0);
        int ans = 0;
        for (int i = nums.size() - 1; i >= 0; i--) {
            long long x = nums[i];
            int lo = lower_bound(vals.begin(), vals.end(), x / 2 + 1) - vals.begin();
            while (lo > 0 && 2 * vals[lo - 1] >= x) lo--;
            while (lo < n && 2 * vals[lo] < x) lo++;
            ans += query(lo);
            int r = lower_bound(vals.begin(), vals.end(), x) - vals.begin() + 1;
            update(r, n);
        }
        return ans;
    }
};

