class Solution {
    private int[] tree;
    private void update(int i, int n) { for (; i <= n; i += i & (-i)) tree[i]++; }
    private int query(int i) { int s = 0; for (; i > 0; i -= i & (-i)) s += tree[i]; return s; }
    public int reversePairs(int[] nums) {
        TreeSet<Long> set = new TreeSet<>();
        for (int x : nums) set.add((long) x);
        List<Long> vals = new ArrayList<>(set);
        int n = vals.size();
        tree = new int[n + 1];
        int ans = 0;
        for (int i = nums.length - 1; i >= 0; i--) {
            long x = nums[i];
            int lo = 0, hi = n;
            while (lo < hi) {
                int m = (lo + hi) >>> 1;
                if (2 * vals.get(m) < x) lo = m + 1; else hi = m;
            }
            ans += query(lo);
            int r = Collections.binarySearch(vals, x) + 1;
            update(r, n);
        }
        return ans;
    }
}

